1	package validation
2	
3	import (
4		"fmt"
5		"regexp"
6		"strings"
7	
8		"github.com/google/cel-go/cel"
9		"github.com/madhuakula/spotter/pkg/models"
10	)
11	
12	// ValidationError represents a validation error
13	type ValidationError struct {
14		Field   string `json:"field"`
15		Message string `json:"message"`
16	}
17	
18	func (e ValidationError) Error() string {
19		return fmt.Sprintf("%s: %s", e.Field, e.Message)
20	}
21	
22	// ValidationResult represents the result of validation
23	type ValidationResult struct {
24		Valid  bool              `json:"valid"`
25		Errors []ValidationError `json:"errors,omitempty"`
26	}
27	
28	// ValidateSpotterRule validates a SpotterRule struct
29	func ValidateSpotterRule(rule *models.SpotterRule) ValidationResult {
30		var errors []ValidationError
31	
32		// Validate APIVersion
33		if rule.APIVersion != "rules.spotter.dev/v1alpha1" {
34			errors = append(errors, ValidationError{
35				Field:   "apiVersion",
36				Message: "must be 'rules.spotter.dev/v1alpha1'",
37			})
38		}
39	
40		// Validate Kind
41		if rule.Kind != "SpotterRule" {
42			errors = append(errors, ValidationError{
43				Field:   "kind",
44				Message: "must be 'SpotterRule'",
45			})
46		}
47	
48		// Validate metadata
49		if rule.Metadata.Name == "" {
50			errors = append(errors, ValidationError{
51				Field:   "metadata.name",
