23	// LoadFromFile loads a SpotterRule or SpotterRulePack from a YAML file
24	func LoadFromFile(filePath string) (*LoadResult, error) {
25		data, err := os.ReadFile(filePath)
26		if err != nil {
27			return nil, fmt.Errorf("failed to read file %s: %w", filePath, err)
28		}
29	
30		return LoadFromBytes(data)
31	}
