34	func LoadFromReader(reader io.Reader) (*LoadResult, error) {
35		data, err := io.ReadAll(reader)
36		if err != nil {
37			return nil, fmt.Errorf("failed to read data: %w", err)
38		}
39	
40		return LoadFromBytes(data)
41	}
42	
43	// LoadFromBytes loads a SpotterRule or SpotterRulePack from YAML bytes
44	func LoadFromBytes(data []byte) (*LoadResult, error) {
45		result := &LoadResult{
46			Rules:     []*models.SpotterRule{},
47			RulePacks: []*models.SpotterRulePack{},
48			Errors:    []error{},
49		}
50	
51		// Split YAML documents if multiple are present
52		documents := strings.Split(string(data), "\n---\n")
53	
54		for i, doc := range documents {
55			doc = strings.TrimSpace(doc)
56			if doc == "" {
57				continue
58			}
59	
60			// First, determine the kind
61			var metadata struct {
62				Kind string `yaml:"kind"`
63			}
64	
65			if err := yaml.Unmarshal([]byte(doc), &metadata); err != nil {
66				result.Errors = append(result.Errors, fmt.Errorf("document %d: failed to parse metadata: %w", i, err))
67				continue
68			}
69	
70			switch metadata.Kind {
71			case "SpotterRule":
72				rule, err := parseSpotterRule([]byte(doc))
73				if err != nil {
74					result.Errors = append(result.Errors, fmt.Errorf("document %d: %w", i, err))
75					continue
76				}
77				result.Rules = append(result.Rules, rule)
78	
79			case "SpotterRulePack":
80				rulePack, err := parseSpotterRulePack([]byte(doc))
81				if err != nil {
82					result.Errors = append(result.Errors, fmt.Errorf("document %d: %w", i, err))
83					continue
84				}
85				result.RulePacks = append(result.RulePacks, rulePack)
86	
87			default:
88				result.Errors = append(result.Errors, fmt.Errorf("document %d: unsupported kind '%s'", i, metadata.Kind))
89			}
90		}
91	
92		return result, nil
93	}
94	
95	// LoadFromDirectory recursively loads all YAML files from a directory
96	func LoadFromDirectory(dirPath string) (*LoadResult, error) {
97		result := &LoadResult{
98			Rules:     []*models.SpotterRule{},
99			RulePacks: []*models.SpotterRulePack{},
100			Errors:    []error{},
101		}
102	
103		err := filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
104			if err != nil {
105				return err
106			}
107	
108			// Skip directories and non-YAML files
109			if info.IsDir() || (!strings.HasSuffix(path, ".yaml") && !strings.HasSuffix(path, ".yml")) {
110				return nil
111			}
112	
113			// Skip test files
114			if strings.Contains(path, "-test.") || strings.Contains(path, "_test.") {
115				return nil
116			}
117	
118			fileResult, err := LoadFromFile(path)
119			if err != nil {
120				result.Errors = append(result.Errors, fmt.Errorf("file %s: %w", path, err))
121				return nil // Continue processing other files
122			}
123	
124			// Merge results
125			result.Rules = append(result.Rules, fileResult.Rules...)
126			result.RulePacks = append(result.RulePacks, fileResult.RulePacks...)
127			result.Errors = append(result.Errors, fileResult.Errors...)
128	
129			return nil
130		})
131	
132		if err != nil {
133			return nil, fmt.Errorf("failed to walk directory %s: %w", dirPath, err)
134		}
135	
136		return result, nil
137	}
138	
139	// ValidateAndLoad loads and validates rules/rulepacks from a file
140	func ValidateAndLoad(filePath string) (*LoadResult, []validation.ValidationResult, error) {
141		result, err := LoadFromFile(filePath)
142		if err != nil {
143			return nil, nil, err
144		}
145	
146		var validationResults []validation.ValidationResult
147	
148		// Validate all loaded rules
149		for _, rule := range result.Rules {
150			validationResult := validation.ValidateSpotterRule(rule)
151			validationResults = append(validationResults, validationResult)
152		}
153	
154		// Validate all loaded rule packs
155		for _, rulePack := range result.RulePacks {
156			validationResult := validation.ValidateSpotterRulePack(rulePack)
157			validationResults = append(validationResults, validationResult)
158		}
159	
160		return result, validationResults, nil
161	}
162	
163	// parseSpotterRule parses YAML data into a SpotterRule
164	func parseSpotterRule(data []byte) (*models.SpotterRule, error) {
165		var rule models.SpotterRule
166		if err := yaml.Unmarshal(data, &rule); err != nil {
167			return nil, fmt.Errorf("failed to parse SpotterRule: %w", err)
168		}
169		return &rule, nil
170	}
171	
172	// parseSpotterRulePack parses YAML data into a SpotterRulePack
173	func parseSpotterRulePack(data []byte) (*models.SpotterRulePack, error) {
174		var rulePack models.SpotterRulePack
175		if err := yaml.Unmarshal(data, &rulePack); err != nil {
176			return nil, fmt.Errorf("failed to parse SpotterRulePack: %w", err)
177		}
178		return &rulePack, nil
179	}
