104	// quickResourceMatch performs a fast pre-filter to check if a resource might match a rule
105	// This avoids expensive CEL compilation and evaluation for obviously non-matching resources
106	func (e *CELEngine) quickResourceMatch(rule *models.SpotterRule, resource map[string]interface{}) bool {
107		// Extract resource metadata
108		apiVersion, _ := resource["apiVersion"].(string)
109		kind, _ := resource["kind"].(string)
110		metadata, _ := resource["metadata"].(map[string]interface{})
111	
112		// Get the kubernetes criteria
113		kubernetesCriteria := rule.Spec.Match.Resources.Kubernetes
114	
115		// Check kind match if specified
116		if len(kubernetesCriteria.Kinds) > 0 {
117			kindMatches := false
118			for _, allowedKind := range kubernetesCriteria.Kinds {
119				if allowedKind == "*" || allowedKind == kind {
120					kindMatches = true
121					break
122				}
123			}
124			if !kindMatches {
125				return false
126			}
127		}
128	
129		// Check API version match if specified
130		if len(kubernetesCriteria.Versions) > 0 {
131			versionMatches := false
132			for _, allowedVersion := range kubernetesCriteria.Versions {
133				if allowedVersion == "*" || apiVersion == allowedVersion {
134					versionMatches = true
135					break
136				}
137				// Also check if the apiVersion contains the version (e.g., "apps/v1" contains "v1")
138				if apiVersion != "" && len(apiVersion) > len(allowedVersion) {
139					if apiVersion[len(apiVersion)-len(allowedVersion):] == allowedVersion {
140						versionMatches = true
141						break
142					}
143				}
144			}
145			if !versionMatches {
146				return false
147			}
148		}
149	
150		// Check API group match if specified
151		if len(kubernetesCriteria.APIGroups) > 0 {
152			groupMatches := false
153			for _, allowedGroup := range kubernetesCriteria.APIGroups {
154				if allowedGroup == "*" {
155					groupMatches = true
156					break
157				}
158				// Core API group is represented as empty string
159				if allowedGroup == "" && (apiVersion == "v1" || !strings.Contains(apiVersion, "/")) {
160					groupMatches = true
161					break
162				}
163				// Check if apiVersion starts with the group
164				if apiVersion != "" && strings.HasPrefix(apiVersion, allowedGroup+"/") {
165					groupMatches = true
166					break
167				}
168			}
169			if !groupMatches {
170				return false
171			}
172		}
173	
174		// Quick namespace check if specified and metadata exists
175		if kubernetesCriteria.Namespaces != nil && metadata != nil {
176			namespace, _ := metadata["namespace"].(string)
177			// Simple include/exclude check - full logic is in MatchesNamespace
178			if len(kubernetesCriteria.Namespaces.Include) > 0 {
179				included := false
180				for _, includePattern := range kubernetesCriteria.Namespaces.Include {
181					if includePattern == "*" || includePattern == namespace {
182						included = true
183						break
184					}
185				}
186				if !included {
187					return false
188				}
189			}
190			if len(kubernetesCriteria.Namespaces.Exclude) > 0 {
191				for _, excludePattern := range kubernetesCriteria.Namespaces.Exclude {
192					if excludePattern == namespace {
193						return false
194					}
195				}
196			}
197		}
198	
199		return true
200	}
