305	// EvaluateRulesAgainstResources evaluates multiple rules against multiple resources
306	func (e *CELEngine) EvaluateRulesAgainstResources(ctx context.Context, rules []*models.SpotterRule, resources []map[string]interface{}) (*models.ScanResult, error) {
307		// Default parallelism
308		return e.EvaluateRulesAgainstResourcesConcurrent(ctx, rules, resources, 10)
309	}
