446	// CompileRule pre-compiles a rule's CEL expression for better performance
447	func (e *CELEngine) CompileRule(ctx context.Context, rule *models.SpotterRule) error {
448		// Check if already compiled
449		if _, exists := e.compiler.GetCompiled(ctx, rule.GetID()); exists {
450			return nil
451		}
452	
453		// Parse CEL expression
454		ast, issues := e.env.Parse(rule.GetCELExpression())
455		if issues != nil && issues.Err() != nil {
456			return fmt.Errorf("failed to parse CEL expression: %w", issues.Err())
457		}
458	
459		// Check the AST
460		checked, issues := e.env.Check(ast)
461		if issues != nil && issues.Err() != nil {
462			return fmt.Errorf("failed to check CEL expression: %w", issues.Err())
463		}
464	
465		// Compile the checked expression to a program
466		program, err := e.env.Program(checked)
467		if err != nil {
468			return fmt.Errorf("failed to compile CEL expression: %w", err)
469		}
470	
471		// Cache compiled program
472		return e.compiler.Compile(ctx, rule.GetID(), program)
473	}
474	
475	// ValidateCELExpression validates a CEL expression without caching
476	// This method provides comprehensive validation including syntax, type checking, and semantic analysis
477	func (e *CELEngine) ValidateCELExpression(ctx context.Context, expression string) error {
478		if strings.TrimSpace(expression) == "" {
479			return fmt.Errorf("CEL expression cannot be empty")
480		}
481	
482		// Parse the expression
483		ast, issues := e.env.Parse(expression)
484		if issues != nil && issues.Err() != nil {
485			return fmt.Errorf("syntax error in CEL expression: %w", issues.Err())
486		}
487	
488		// Type-check the expression
489		checked, issues := e.env.Check(ast)
490		if issues != nil && issues.Err() != nil {
491			return fmt.Errorf("type checking failed for CEL expression: %w", issues.Err())
492		}
493	
494		// Validate return type - must be boolean for rule evaluation
495		if !checked.OutputType().IsExactType(cel.BoolType) {
496			return fmt.Errorf("CEL expression must return boolean type for rule evaluation, got %s", checked.OutputType())
497		}
498	
499		// Attempt to compile to catch any compilation issues
500		_, err := e.env.Program(checked)
501		if err != nil {
502			return fmt.Errorf("compilation failed for CEL expression: %w", err)
503		}
504	
505		return nil
506	}
507	
508	// ResourceMatcher implementation
509	type resourceMatcher struct{}
510	
511	// NewResourceMatcher creates a new resource matcher
512	func NewResourceMatcher() ResourceMatcher {
513		return &resourceMatcher{}
514	}
515	
516	// MatchesRule checks if a resource matches the rule's match criteria
517	func (m *resourceMatcher) MatchesRule(ctx context.Context, rule *models.SpotterRule, resource map[string]interface{}) (bool, error) {
518		// Extract resource metadata
519		apiVersion, _ := resource["apiVersion"].(string)
520		kind, _ := resource["kind"].(string)
521		metadata, _ := resource["metadata"].(map[string]interface{})
522	
523		if metadata == nil {
524			return false, fmt.Errorf("resource metadata is missing")
525		}
526	
527		namespace, _ := metadata["namespace"].(string)
528		labels := make(map[string]string)
529		if labelMap, ok := metadata["labels"].(map[string]interface{}); ok {
530			for k, v := range labelMap {
531				if strVal, ok := v.(string); ok {
532					labels[k] = strVal
533				}
534			}
535		}
536	
537		// Check kind match
538		matches, err := m.MatchesKind(ctx, apiVersion, kind, &rule.Spec.Match.Resources.Kubernetes)
539		if err != nil || !matches {
540			return matches, err
541		}
542	
543		// Check namespace match
544		if rule.Spec.Match.Resources.Kubernetes.Namespaces != nil {
545			matches, err = m.MatchesNamespace(ctx, namespace, rule.Spec.Match.Resources.Kubernetes.Namespaces)
546			if err != nil || !matches {
547				return matches, err
548			}
549		}
550	
551		// Check label match
552		if rule.Spec.Match.Resources.Kubernetes.Labels != nil {
553			matches, err = m.MatchesLabels(ctx, labels, rule.Spec.Match.Resources.Kubernetes.Labels)
554			if err != nil || !matches {
555				return matches, err
556			}
557		}
558	
559		return true, nil
560	}
561	
562	// MatchesNamespace checks if a resource's namespace matches the namespace selector
563	func (m *resourceMatcher) MatchesNamespace(ctx context.Context, namespace string, selector *models.NamespaceSelector) (bool, error) {
564		// Check exclusions first
565		for _, exclude := range selector.Exclude {
566			if matched, _ := filepath.Match(exclude, namespace); matched {
567				return false, nil
568			}
569		}
570	
571		// Check inclusions
572		if len(selector.Include) == 0 {
573			return true, nil // No inclusions means all namespaces are included
574		}
575	
576		for _, include := range selector.Include {
577			if include == "*" || include == namespace {
578				return true, nil
579			}
580			if matched, _ := filepath.Match(include, namespace); matched {
581				return true, nil
582			}
583		}
584	
585		return false, nil
586	}
587	
588	// MatchesLabels checks if a resource's labels match the label selector
589	func (m *resourceMatcher) MatchesLabels(ctx context.Context, labels map[string]string, selector *models.LabelSelector) (bool, error) {
590		// Check exclusions first
591		for key, values := range selector.Exclude {
592			if labelValue, exists := labels[key]; exists {
593				for _, value := range values {
594					if value == labelValue {
595						return false, nil
596					}
597				}
598			}
599		}
600	
601		// Check inclusions
602		for key, values := range selector.Include {
603			labelValue, exists := labels[key]
604			if !exists {
605				return false, nil
606			}
607	
608			found := false
609			for _, value := range values {
610				if value == labelValue {
611					found = true
612					break
613				}
614			}
615			if !found {
616				return false, nil
617			}
618		}
619	
620		return true, nil
621	}
622	
623	// MatchesKind checks if a resource kind matches the rule criteria
624	func (m *resourceMatcher) MatchesKind(ctx context.Context, apiVersion, kind string, criteria *models.KubernetesResourceCriteria) (bool, error) {
625		// Parse API version
626		parts := strings.Split(apiVersion, "/")
627		var group, version string
628		if len(parts) == 1 {
629			group = ""
630			version = parts[0]
631		} else {
632			group = parts[0]
633			version = parts[1]
634		}
635	
636		// Check API group
637		groupMatches := false
638		for _, allowedGroup := range criteria.APIGroups {
639			if allowedGroup == group {
640				groupMatches = true
641				break
642			}
643		}
644		if !groupMatches {
645			return false, nil
646		}
647	
648		// Check version
649		versionMatches := false
650		for _, allowedVersion := range criteria.Versions {
651			if allowedVersion == version {
652				versionMatches = true
653				break
654			}
655		}
656		if !versionMatches {
657			return false, nil
658		}
659	
660		// Check kind
661		kindMatches := false
662		for _, allowedKind := range criteria.Kinds {
663			if allowedKind == kind {
664				kindMatches = true
665				break
666			}
667		}
668	
669		return kindMatches, nil
670	}
671	
672	// RuleCompiler implementation
673	type ruleCompiler struct {
674		cache map[string]cel.Program
675		mu    sync.RWMutex
676	}
677	
678	// NewRuleCompiler creates a new rule compiler
679	func NewRuleCompiler() RuleCompiler {
680		return &ruleCompiler{
681			cache: make(map[string]cel.Program),
682		}
683	}
684	
685	// Compile compiles a CEL expression and caches the compiled program
686	func (c *ruleCompiler) Compile(ctx context.Context, ruleID string, program cel.Program) error {
687		c.mu.Lock()
688		defer c.mu.Unlock()
689		c.cache[ruleID] = program
690		return nil
691	}
692	
693	// GetCompiled retrieves a compiled CEL program
694	func (c *ruleCompiler) GetCompiled(ctx context.Context, ruleID string) (interface{}, bool) {
695		c.mu.RLock()
696		defer c.mu.RUnlock()
697		program, exists := c.cache[ruleID]
698		return program, exists
699	}
700	
701	// ClearCache clears the compilation cache
702	func (c *ruleCompiler) ClearCache(ctx context.Context) {
703		c.mu.Lock()
704		defer c.mu.Unlock()
705		c.cache = make(map[string]cel.Program)
706	}
707	
708	// GetCacheStats returns cache statistics
709	func (c *ruleCompiler) GetCacheStats(ctx context.Context) map[string]interface{} {
710		c.mu.RLock()
711		defer c.mu.RUnlock()
712		return map[string]interface{}{
713			"size": len(c.cache),
714		}
715	}
